self.KB_CONTENT["card:756008"]={"id":"card:756008","ty":"card","sourceId":"756008","title":"『銷退單明細表』的作業目的為何？","ver":"iGP","topic":"明細表","keywords":["明細表","銷退單"],"y":"explain","answer":"由「銷退單建立作業」將銷退單之原始資料，以資料清單格式列印。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
