self.KB_CONTENT["card:779564"]={"id":"card:779564","ty":"card","sourceId":"779564","title":"『委工單單據性質設定作業』中的『控管品號生失效 (MQ040)』為何？","ver":"GP4以上","topic":"品號","keywords":["品號","工單","失效","控管"],"y":"other","answer":"* 僅能輸入Y/N。* 預設Y。* 分為Y.不控管品號生失效及N.控管品號生失效兩種。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
