self.KB_CONTENT["card:783288"]={"id":"card:783288","ty":"card","sourceId":"783288","title":"『接軌轉換作業(介面程式)』中的『步驟七:轉換結果驗證』為何？","ver":"GP4以上","topic":"完成","keywords":["完成","結果","成功"],"y":"other","answer":"* 此欄位僅做顯示。* 若 [步驟七:轉換結果驗證]='Y'，CALL BACB09 轉換結果驗證作業。* 若轉換完成，則表示接軌轉換執行成功。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
