self.KB_CONTENT["field:778291"]={"id":"field:778291","ty":"field","sourceId":"778291","title":".簽核狀態","ver":"GP4以上","topic":"","keywords":[],"job":"領料單建立作業","code":"TC016","answer":"* 此欄位僅作顯示。簽核狀態類型區分為0.待處理、1.簽核中、2.退件、3.已核准、4.取消確認中、5.作廢中、6.取消作廢中及N.不執行電子簽核。","file":"fields.jsonl"};
